	@Test
	void semanticImportPreservesNullPresenceWithoutTransferringGraphOrigin() {
		QueryBindingSet source = source();
		ArrayBindingSet target = arrayContext(NAMES).createBindingSet(source);
		BindingSetImport importer = target;
		assertTrue(GraphFrameBindings.isSupplied(target, "graph"));
		importer.setBindingFromCopy("graph", null);
		assertTrue(target.hasBinding("graph"));
		assertNull(target.getBinding("graph"));
		assertNull(target.getValue("graph"));
		assertFalse(GraphFrameBindings.isSupplied(target, "graph"));
		assertEquals(List.of("graph", "keep", "x", "y"), target.getSortedBindingNames());
		assertEquals(4, target.size());
		importer.setBindingFromCopy("graph", RDF.NIL);
		assertEquals(RDF.NIL, target.getValue("graph"));
		assertFalse(GraphFrameBindings.isSupplied(target, "graph"));
		target.setBinding("graph", null);
		assertFalse(target.hasBinding("graph"), "ordinary local null setters keep their absence contract");
		assertEquals(3, target.size());
		assertTrue(GraphFrameBindings.isSupplied(source, "graph"));
		assertSame(BindingFrameBindings.from(source), BindingFrameBindings.from(target));
	}

