	@Test
	void metadataCopiesPreserveExistingTargetOriginAndKeepMissingGrantsLatent() {
		QueryBindingSet source = source();
		ArrayBindingSet projected = new ArrayBindingSet(source, Set.of("keep"), new String[] { "keep" });
		QueryBindingSet localTarget = new QueryBindingSet();
		localTarget.setBinding("graph", RDF.NIL);
		GraphFrameBindings.preserve(projected, localTarget);
		assertEquals(RDF.NIL, localTarget.getValue("graph"));
		assertFalse(GraphFrameBindings.isSupplied(localTarget, "graph"));
		QueryBindingSet suppliedTarget = new QueryBindingSet();
		GraphFrameBindings.supply(suppliedTarget, "graph", RDF.NIL);
		GraphFrameBindings existing = GraphFrameBindings.from(suppliedTarget);
		suppliedTarget.addAll(projected);
		assertSame(existing, GraphFrameBindings.from(suppliedTarget));
		assertTrue(GraphFrameBindings.isSupplied(suppliedTarget, "graph"));
		QueryBindingSet pureCopy = new QueryBindingSet(projected);
		assertFalse(pureCopy.hasBinding("graph"));
		assertSame(GraphFrameBindings.from(source), GraphFrameBindings.from(pureCopy));
	}

	@Test
	void frameAndGraphMetadataDoNotChangeLogicalSetOrGroupingKeys() {
		QueryBindingSet framed = source();
		QueryBindingSet plain = new QueryBindingSet();
		for (String name : framed.getBindingNames()) {
			plain.setBinding(name, framed.getValue(name));
		}
		List<BindingSet> equivalents = List.of(framed, plain, new ReadOnlyBindings(framed),
				arrayContext(NAMES).createBindingSet(framed), arrayContext(NAMES).createBindingSet(plain));
		assertEquals(1, new HashSet<>(equivalents).size());
		Map<BindingSet, Integer> counts = new HashMap<>();
		for (BindingSet row : equivalents) {
			counts.merge(row, 1, Integer::sum);
			assertLogicalCopy(plain, row);
		}
		assertEquals(1, counts.size());
		assertEquals(equivalents.size(), counts.get(plain).intValue());
	}

