	@Test
	void arrayCopiesRemapImportedNullNamesAndKeepIndependentCaches() {
		QueryBindingSet source = source();
		ArrayBindingSet original = arrayContext(NAMES).createBindingSet(source);
		original.getDirectSetBinding("placeholder").accept(null, original);
		assertLogicalCopy(source, original);
		assertEquals(List.of("graph", "keep", "x", "y"), original.getSortedBindingNames());
		ArrayBindingSet[] copies = { new ArrayBindingSet(original, NAMES),
				new ArrayBindingSet(original, NAMES.clone()),
				new ArrayBindingSet(original, "graph", "placeholder", "y", "keep", "x"),
				new ArrayBindingSet(new ReadOnlyBindings(original), Set.of(NAMES), NAMES) };
		for (ArrayBindingSet copy : copies) {
			assertLogicalCopy(source, copy);
			assertSame(BindingFrameBindings.from(original), BindingFrameBindings.from(copy));
			assertSame(GraphFrameBindings.from(original), GraphFrameBindings.from(copy));
			assertEquals(original.getSortedBindingNames(), copy.getSortedBindingNames());
			assertFalse(copy.hasBinding("placeholder"));
			copy.removeBinding("x");
			assertFalse(copy.hasBinding("x"));
			assertEquals(3, copy.size());
			assertEquals(List.of("graph", "keep", "y"), copy.getSortedBindingNames());
			assertTrue(original.hasBinding("x"), "copied null-presence state must not be shared");
		}
		ArrayBindingSet projected = new ArrayBindingSet(original, "x", "keep");
		QueryBindingSet expected = new QueryBindingSet();
		expected.setBinding("x", null);
		expected.setBinding("keep", RDF.TYPE);
		assertLogicalCopy(expected, projected);
		assertSame(BindingFrameBindings.from(original), BindingFrameBindings.from(projected));
		assertSame(GraphFrameBindings.from(original), GraphFrameBindings.from(projected));
	}

	@Test
	void nullOnlyArraysDistinguishAbsentAndOtherNullNamesAcrossLayouts() {
		String[] layout = { "x", "y" };
		QueryBindingSet nullX = new QueryBindingSet();
		nullX.setBinding("x", null);
		ArrayBindingSet first = arrayContext(layout).createBindingSet(nullX);
		ArrayBindingSet same = new ArrayBindingSet(first, layout);
		ArrayBindingSet reordered = new ArrayBindingSet(first, "y", "x");
		for (BindingSet copy : List.of(first, same, reordered, new QueryBindingSet(first))) {
			assertLogicalCopy(nullX, copy);
			assertFalse(copy.isEmpty());
			assertFalse(copy.iterator().hasNext());
			assertNotEquals(copy, EmptyBindingSet.getInstance());
		}
		QueryBindingSet nullY = new QueryBindingSet();
		nullY.setBinding("y", null);
		ArrayBindingSet otherName = new ArrayBindingSet(nullY, Set.of(layout), layout);
		assertNotEquals(first, otherName);
		assertNotEquals(otherName, first);
		ArrayBindingSet valuedX = new ArrayBindingSet(layout);
		valuedX.setBinding("x", RDF.TYPE);
		assertNotEquals(first, valuedX);
		assertNotEquals(valuedX, first);
		first.getDirectSetBinding("x").accept(null, first);
		assertTrue(first.isEmpty());
		assertEquals(new ArrayBindingSet(layout), first);
		assertTrue(same.hasBinding("x"));
	}

	@ParameterizedTest
	@EnumSource(LocalMutation.class)
	void everyLocalArrayWriteOrRemovalReplacesImportedNullPresence(LocalMutation mutation) {
		QueryBindingSet source = new QueryBindingSet();
		source.setBinding("x", null);
		ArrayBindingBasedQueryEvaluationContext context = arrayContext(new String[] { "x" });
		ArrayBindingSet copy = context.createBindingSet(source);
		assertTrue(context.hasBinding("x").test(copy));
		assertEquals(List.of("x"), copy.getSortedBindingNames());
		mutation.apply(context, copy);
		boolean valued = mutation.valued;
		assertEquals(valued, copy.hasBinding("x"));
		assertEquals(valued, context.hasBinding("x").test(copy));
		assertEquals(valued ? RDF.TYPE : null, copy.getValue("x"));
		assertEquals(valued ? Set.of("x") : Set.of(), copy.getBindingNames());
		assertEquals(valued ? List.of("x") : List.of(), copy.getSortedBindingNames());
		assertEquals(valued ? 1 : 0, copy.size());
		assertEquals(!valued, copy.isEmpty());
		assertEquals(copy, new QueryBindingSet(copy));
		assertEquals(copy.hashCode(), new QueryBindingSet(copy).hashCode());
		assertTrue(source.hasBinding("x"));
		assertNull(source.getValue("x"));
	}

	@Test
	void bulkArrayCopyReplacesNullPresenceAndPreservesSourceOrigins() {
		for (String[] layout : new String[][] { NAMES, { "graph", "x", "placeholder", "keep", "y" } }) {
			QueryBindingSet source = source();
			source.removeBinding("y");
			ArrayBindingSet incoming = arrayContext(NAMES).createBindingSet(source);
			QueryBindingSet old = new QueryBindingSet();
			old.setBinding("x", RDF.ALT);
			old.setBinding("y", null);
			ArrayBindingSet target = arrayContext(layout).createBindingSet(old);
			target.addAll(incoming);
			QueryBindingSet expected = new QueryBindingSet(source);
			expected.setBinding("y", null);
			assertLogicalCopy(expected, target);
			assertSame(BindingFrameBindings.from(source), BindingFrameBindings.from(target));
			assertTrue(GraphFrameBindings.isSupplied(target, "graph"));
			ArrayBindingSet placeholders = new ArrayBindingSet(layout);
			placeholders.getDirectSetBinding("x").accept(null, placeholders);
			target.addAll(placeholders);
			assertTrue(target.hasBinding("x"), "absent source placeholders do not replace a null shadow");
			ArrayBindingSet local = new ArrayBindingSet(layout);
			local.setBinding("x", RDF.TYPE);
			local.setBinding("graph", RDF.NIL);
			target.addAll(local);
			assertEquals(RDF.TYPE, target.getValue("x"));
			assertFalse(GraphFrameBindings.isSupplied(target, "graph"));
			target.removeBinding("x");
			assertFalse(target.hasBinding("x"), "a replaced null shadow cannot reappear on removal");
		}
	}

	@Test
	void largeArrayLayoutsPreserveNullNamesBeyondSingleMaskWidth() {
		String[] layout = new String[70];
		Arrays.setAll(layout, index -> "v" + index);
		QueryBindingSet source = new QueryBindingSet();
		for (int index : new int[] { 0, 63, 64, 69 }) {
			source.setBinding(layout[index], null);
		}
		source.setBinding("v32", RDF.TYPE);
		ArrayBindingBasedQueryEvaluationContext context = arrayContext(layout);
		ArrayBindingSet copy = context.createBindingSet(source);
		assertLogicalCopy(source, copy);
		ArrayList<String> expectedNames = new ArrayList<>(source.getBindingNames());
		expectedNames.sort(String::compareTo);
		assertEquals(expectedNames, copy.getSortedBindingNames());
		assertTrue(context.hasBinding("v64").test(copy));
		context.removeBinding("v64").accept(copy);
		assertFalse(copy.hasBinding("v64"));
		assertFalse(context.hasBinding("v64").test(copy));
		assertTrue(copy.hasBinding("v0"));
		assertTrue(copy.hasBinding("v63"));
		assertTrue(copy.hasBinding("v69"));
	}

	@Test
	void queryCopiesRespectRemoveRetainAndClearOfLogicalNullNames() {
		QueryBindingSet source = source();
		QueryBindingSet copy = new QueryBindingSet(new ReadOnlyBindings(source));
		copy.removeBinding("x");
		copy.removeAll(Set.of("y", "graph"));
		assertEquals(Set.of("keep"), copy.getBindingNames());
		assertFalse(GraphFrameBindings.isSupplied(copy, "graph"));
		copy.setBinding("graph", RDF.NIL);
		assertFalse(GraphFrameBindings.isSupplied(copy, "graph"));
		copy.addAll(new ReadOnlyBindings(source));
		assertLogicalCopy(source, copy);
		assertTrue(GraphFrameBindings.isSupplied(copy, "graph"));
		copy.retainAll(Set.of("x", "keep"));
		assertEquals(Set.of("x", "keep"), copy.getBindingNames());
		assertTrue(copy.hasBinding("x"));
		copy.getBindingNames().clear();
		assertTrue(copy.isEmpty());
		assertTrue(new QueryBindingSet(copy).isEmpty());
		assertEquals(Set.of("x", "y", "keep", "graph"), source.getBindingNames());
	}

	@Test
	void importedNullShadowsSurviveJavaSerialization() throws Exception {
		for (QueryBindingSet source : List.of(source(), nullOnlySource())) {
			ArrayBindingSet original = arrayContext(NAMES).createBindingSet(source);
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
				output.writeObject(original);
			}
			ArrayBindingSet restored;
			try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
				restored = (ArrayBindingSet) input.readObject();
			}
			assertLogicalCopy(source, restored);
			assertLogicalCopy(source, new QueryBindingSet(restored));
			assertLogicalCopy(source, new ArrayBindingSet(restored, NAMES));
			if (source.hasBinding("graph")) {
				assertTrue(GraphFrameBindings.isSupplied(restored, "graph"));
				assertNotNull(BindingFrameBindings.from(restored));
				assertEquals(RDF.ALT, BindingFrameBindings.probeValue(restored, "hidden"));
			}
		}
	}

	private static void assertLogicalCopy(BindingSet expected, BindingSet copy) {
		assertEquals(expected.getBindingNames(), copy.getBindingNames());
		assertEquals(expected.size(), copy.size());
		assertEquals(expected.isEmpty(), copy.isEmpty());
		assertEquals(expected, copy);
		assertEquals(copy, expected);
		assertEquals(expected.hashCode(), copy.hashCode());
		for (String name : expected.getBindingNames()) {
			assertTrue(copy.hasBinding(name));
			assertEquals(expected.getValue(name), copy.getValue(name));
			if (expected.getValue(name) == null) {
				assertNull(copy.getBinding(name));
			}
		}
		MapBindingSet exported = new MapBindingSet();
		for (Binding binding : copy) {
			assertNotNull(binding);
			assertNotNull(binding.getValue());
			exported.addBinding(binding);
		}
		for (String name : expected.getBindingNames()) {
			assertEquals(expected.getValue(name) != null, exported.hasBinding(name));
		}
	}

	private static ArrayBindingBasedQueryEvaluationContext arrayContext(String[] names) {
		return new ArrayBindingBasedQueryEvaluationContext(CONTEXT, names, null);
	}

	private static QueryBindingSet nullOnlySource() {
		QueryBindingSet source = new QueryBindingSet();
		source.setBinding("x", null);
		return source;
	}

	private static QueryBindingSet source() {
		QueryBindingSet source = nullOnlySource();
		source.setBinding("y", null);
		source.setBinding("keep", RDF.TYPE);
		GraphFrameBindings.supply(source, "graph", RDF.NIL);
		QueryBindingSet probes = new QueryBindingSet();
		probes.setBinding("hidden", RDF.ALT);
		BindingSet framed = BindingFrameBindings.push(new BindingFrameBindings.Scope(),
				EmptyBindingSet.getInstance(), probes, CONTEXT);
		source.setBindingFrame(BindingFrameBindings.from(framed));
		return source;
	}

	private enum Copy {
		DIRECT,
		MINIMAL_CONTEXT,
		NAMED_CONTEXT,
		ARRAY_CONTEXT;

		MutableBindingSet copy(BindingSet bindings) {
			return switch (this) {
			case DIRECT -> new QueryBindingSet(bindings);
			case MINIMAL_CONTEXT -> CONTEXT.createBindingSet(bindings);
			case NAMED_CONTEXT -> new BindingSetQueryEvaluationContext(CONTEXT).createBindingSet(bindings);
			case ARRAY_CONTEXT -> arrayContext(NAMES).createBindingSet(bindings);
			};
		}
	}

	private enum LocalMutation {
		DIRECT_SET_VALUE(true),
		DIRECT_SET_NULL(false),
		DIRECT_ADD_VALUE(true),
		DIRECT_ADD_NULL(false),
		SET_VALUE(true),
		SET_NULL(false),
		SET_BINDING(true),
		ADD_BINDING(true),
		REMOVE(false),
		CONTEXT_SET_NULL(false),
		CONTEXT_ADD_NULL(false),
		CONTEXT_REMOVE(false);

		private final boolean valued;

		LocalMutation(boolean valued) {
			this.valued = valued;
		}

		void apply(ArrayBindingBasedQueryEvaluationContext context, ArrayBindingSet bindings) {
			switch (this) {
			case DIRECT_SET_VALUE -> bindings.getDirectSetBinding("x").accept(RDF.TYPE, bindings);
			case DIRECT_SET_NULL -> bindings.getDirectSetBinding("x").accept(null, bindings);
			case DIRECT_ADD_VALUE -> bindings.getDirectAddBinding("x").accept(RDF.TYPE, bindings);
			case DIRECT_ADD_NULL -> bindings.getDirectAddBinding("x").accept(null, bindings);
			case SET_VALUE -> bindings.setBinding("x", RDF.TYPE);
			case SET_NULL -> bindings.setBinding("x", null);
			case SET_BINDING -> bindings.setBinding(new SimpleBinding("x", RDF.TYPE));
			case ADD_BINDING -> bindings.addBinding(new SimpleBinding("x", RDF.TYPE));
			case REMOVE -> bindings.removeBinding("x");
			case CONTEXT_SET_NULL -> context.setBinding("x").accept(null, bindings);
			case CONTEXT_ADD_NULL -> context.addBinding("x").accept(null, bindings);
			case CONTEXT_REMOVE -> context.removeBinding("x").accept(bindings);
			}
		}
	}

	private static final class ReadOnlyBindings extends AbstractBindingSet
			implements BindingFrameBindings.Carrier, GraphFrameBindings.Carrier {
		private static final long serialVersionUID = 1L;
		private final BindingSet source;

		private ReadOnlyBindings(BindingSet source) {
			this.source = source;
		}

		@Override
		public Iterator<Binding> iterator() {
			return source.iterator();
		}

		@Override
		public Set<String> getBindingNames() {
			return source.getBindingNames();
		}

		@Override
		public Binding getBinding(String name) {
			return source.getBinding(name);
		}

		@Override
		public Value getValue(String name) {
			return source.getValue(name);
		}

		@Override
		public boolean hasBinding(String name) {
			return source.hasBinding(name);
		}

		@Override
		public int size() {
			return source.size();
		}

		@Override
		public BindingFrame getBindingFrame() {
			return BindingFrameBindings.from(source);
		}

		@Override
		public GraphFrameBindings getGraphFrameBindings() {
			return GraphFrameBindings.from(source);
		}
	}
